describe('ARIA Landmarks for Page Regions', () => {
  beforeEach(() => {
    cy.visit('/landmarks-test');
  });

  it('should correctly apply ARIA landmarks to page regions', () => {
    // Verify main navigation landmark is present
    cy.get('[data-testid="main-navigation"]').should('be.visible');
    cy.get('[data-testid="main-navigation"]').should('have.attr', 'aria-label', 'Main navigation');

    // Verify main content landmark is present
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="main-content"]').should('have.attr', 'aria-label', 'Main content');

    // Verify footer landmark is present
    cy.get('[data-testid="footer"]').should('be.visible');
    cy.get('[data-testid="footer"]').should('have.attr', 'aria-label', 'Footer');

    // Verify sidebar landmark is present
    cy.get('[data-testid="sidebar"]').should('be.visible');
    cy.get('[data-testid="sidebar"]').should('have.attr', 'aria-label', 'Sidebar');

    // Verify search landmark is present
    cy.get('[data-testid="search-bar"]').should('be.visible');
    cy.get('[data-testid="search-bar"]').should('have.attr', 'aria-label', 'Search');

    // Verify modal landmark is present
    cy.get('[data-testid="modal-dialog"]').should('be.visible');
    cy.get('[data-testid="modal-dialog"]').should('have.attr', 'aria-label', 'Modal dialog');

    // Verify error state landmark is present
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-live', 'polite');
  });

  it('should handle ARIA landmarks when page content is dynamically loaded', () => {
    // Verify main navigation landmark is present before content loads
    cy.get('[data-testid="main-navigation"]').should('be.visible');

    // Load content dynamically
    cy.intercept('GET', '/api/content').as('loadContent');
    cy.wait('@loadContent');

    // Verify main content landmark is still present after content loads
    cy.get('[data-testid="main-content"]').should('be.visible');

    // Verify footer landmark is still present after content loads
    cy.get('[data-testid="footer"]').should('be.visible');

    // Verify sidebar landmark is still present after content loads
    cy.get('[data-testid="sidebar"]').should('be.visible');

    // Verify search landmark is still present after content loads
    cy.get('[data-testid="search-bar"]').should('be.visible');

    // Verify modal landmark is still present after content loads
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify error state landmark is still present after content loads
    cy.get('[data-testid="error-message"]').should('be.visible');
  });
});
